<?php
require_once '../config.php';require_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$status=$_POST['status']??'Pending';$pay=$_POST['payment_status']??'Unverified';
if(in_array($status,['Pending','Confirmed','Processing','Shipped','Delivered','Cancelled'],true)&&in_array($pay,['Unverified','Verified','Rejected'],true)){$s=$pdo->prepare("UPDATE orders SET status=?,payment_status=? WHERE id=?");$s->execute([$status,$pay,$id]);}
header('Location: orders.php');exit;}
$orders=$pdo->query("SELECT * FROM orders ORDER BY created_at DESC")->fetchAll();
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Orders</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><header class="site-header"><a class="brand" href="index.php">ZY<span>ADMIN</span></a><nav><a href="index.php">Dashboard</a><a href="products.php">Products</a><a href="orders.php">Orders</a></nav><a href="logout.php">Logout</a></header><main class="section"><h1>Customer orders</h1><div class="table-wrap"><table><tr><th>Order / date</th><th>Customer</th><th>Delivery</th><th>Payment reference</th><th>Total</th><th>Update</th></tr><?php foreach($orders as $o):?><tr><td>#<?=(int)$o['id']?><br><small><?=e($o['created_at'])?></small></td><td><?=e($o['customer_name'])?><br><?=e($o['phone'])?><br><?=e($o['email']??'')?></td><td><?=nl2br(e($o['address']))?></td><td><?=e($o['payment_method'])?><br><?=e($o['payment_reference'])?><br><strong><?=e($o['payment_status'])?></strong></td><td><?=money((float)$o['total'])?></td><td><form method="post" class="mini-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$o['id']?>"><select name="status"><?php foreach(['Pending','Confirmed','Processing','Shipped','Delivered','Cancelled'] as $v):?><option <?=$o['status']===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select><select name="payment_status"><?php foreach(['Unverified','Verified','Rejected'] as $v):?><option <?=$o['payment_status']===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select><button class="button small">Update</button></form></td></tr><?php endforeach;?></table></div></main></body></html>
